# Check if these numbers are primes
def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

nums = [1424, 959]
for n in nums:
    print(f'{n} is prime: {is_prime(n)}')

# Factor them
for n in nums:
    factors = []
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors.append(d)
            temp //= d
        d += 1
    if temp > 1:
        factors.append(temp)
    print(f'{n} = {\" * \".join(map(str, factors))}')
"

